function o(){document.querySelectorAll("amp-youtube").forEach(t=>{const i=t.getAttribute("data-videoid")||t.getAttribute("data-embed");if(i){if(!t.querySelector("img")){const e=document.createElement("img");e.src=`https://i.ytimg.com/vi_webp/${i}/hqdefault.webp`,e.srcset=`
        https://i.ytimg.com/vi_webp/${i}/mqdefault.webp 320w,
        https://i.ytimg.com/vi_webp/${i}/hqdefault.webp 480w,
        https://i.ytimg.com/vi_webp/${i}/sddefault.webp 640w,
        https://i.ytimg.com/vi_webp/${i}/maxresdefault.webp 1280w
      `,e.sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 640px",e.alt="YouTube video thumbnail",e.className="w-full h-full object-cover",e.loading="lazy",e.onerror=()=>{e.removeAttribute("srcset"),e.src=`https://img.youtube.com/vi/${i}/hqdefault.jpg`},t.appendChild(e)}t.addEventListener("click",e=>{e.preventDefault();const l=document.createElement("iframe");l.src=`https://www.youtube.com/embed/${i}?rel=0&showinfo=0&autoplay=1`,l.title="YouTube video player",l.className="w-full h-full absolute inset-0 border-0 rounded-xl loaded z-20",l.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",l.referrerPolicy="strict-origin-when-cross-origin",l.allowFullscreen=!0,t.innerHTML="",t.appendChild(l),t.classList.add("playing")})}})}export{o as initLazyYoutube};
